					tpd.TRADE_MARKET in ('01','02') and (

					(tpd.FINPROD_TYPE2 ='F01' and tpd.PS in ('T01','T02','T03'))

					or (tpd.FINPROD_TYPE2 in ('F02','F03'))

					or (tpd.FINPROD_TYPE2 ='F32' and tpd.PS ='T01')
