					tpd.TRADE_MARKET in ('03','04') and (

					(tpd.FINPROD_TYPE2 ='F01' and tpd.PS in ('T01','T02','T03','T05','T97'))

					or (tpd.FINPROD_TYPE2 ='F01' and tpd.PS = 'T04' and tdta.PURCH_MODLE = '01')

					or (tpd.FINPROD_TYPE2 in ('F02','F03') and fpt.TYPE_6='H02')

					or (tpd.FINPROD_TYPE2 ='F32' and tpd.PS ='T01')

					or (tpd.FINPROD_TYPE2 ='F06' and tpd.PS in ('T01','T02'))

					or (tpd.FINPROD_TYPE2 ='F10' and tpd.PS in ('T01','T02','T05','T46'))

					or (tpd.FINPROD_TYPE2 ='F37' and tpd.PS in ('T01','T02','T04'))
					)
				)
			)
		)

		SELECT * FROM (
        (

			WFL_TRD_PRODUCT_DEAL.TOTLE_TRADE_ID is null


