						     OR (USER_ROLE_POST.ISTRADERCOUNT>0 AND WFL_TRD_PRODUCT_DEAL.TRADER = USER_ROLE_POST.USER_ID )
			    			)

		)

		union all
		(



            NOT EXISTS (
