				OR FIN_PRODUCT.FINPROD_ABBR LIKE concat(concat('%',#{finprodMarketId,jdbcType=VARCHAR}),'%')
				OR FIN_PRODUCT.FINPROD_ID LIKE CONCAT('%', CONCAT(#{finprodMarketId}, '%'))
				OR FIN_PRODUCT_ADD.APPEAR_MARKET_ID LIKE CONCAT('%', CONCAT(#{finprodMarketId}, '%'))
				)


				AND (WFL_TRD_FIN_PRODUCT_DEAL_TOTAL.FINPROD_TYPE2 IN(

    						#{item}

