                FIN_PRODUCT.PROFIT_TYPE IN(

                    #{item}

                )


                AND WFL_TRD_PRODUCT_DEAL.FINPROD_TYPE2 IN(

                    #{item}

                )
                )



                AND INSTR(#{prodPs},WFL_TRD_PRODUCT_DEAL.PS) > 0



                AND WFL_TRD_PRODUCT_DEAL.TRADE_MARKET = #{tradeMarket}





                        AND WFL_TRD_PRODUCT_DEAL.TRADE_MARKET_MODE = #{tradeMarketMode}


                        AND (WFL_TRD_PRODUCT_DEAL.TRADE_MARKET_MODE = '02'
                        or WFL_TRD_PRODUCT_DEAL.TRADE_MARKET_MODE IS NULL
                        or WFL_TRD_PRODUCT_DEAL.TRADE_MARKET_MODE = '')




                AND (WFL_TRD_PRODUCT_DEAL.CHL_ID IN


