                    #{finType_F05},#{finType_F08},#{finType_F09},#{finType_F11},
                    #{finType_F12},#{finType_F13},#{finType_F25},#{finType_F29},#{finType_F30})
                    then WFL_PA_TRD_PRODUCT_DEAL.BACK_LEND_DIRECTION

                else WFL_TRD_PRODUCT_DEAL.PS
                end ) = #{ps}




                        AND MST_COUNTER_PARTY.COUNTER_TYPE = #{COUNTER_TYPE_05}


                        AND ( MST_COUNTER_PARTY.COUNTER_TYPE != #{COUNTER_TYPE_05} OR MST_COUNTER_PARTY.COUNTER_TYPE IS NULL )




                 AND to_char(WFL_TRD_PRODUCT_DEAL.TRADE_DATE,'yyyy-MM-dd')  >= #{beginDate} 


