            (USER_ROLE_POST.ISMANAGERCOUNT>0 AND EXISTS (SELECT 1 FROM PTL_PORTFOLIO_AUTHORITY PPA WHERE PPA.USER_ID = USER_ROLE_POST.USER_ID AND PPA.PORTFOLIO_ID = WFL_TRD_PRODUCT_DEAL_ADD.PORTFOLIO_ID))
            OR (USER_ROLE_POST.ISTRADERCOUNT>0 AND WFL_TRD_PRODUCT_DEAL.TRADER = USER_ROLE_POST.USER_ID )
            )

        )

        union all
        (


            AND EXISTS (
            SELECT 1 FROM WFL_TRD_FIN_PRODUCT_DEAL_TOTAL tpd left join FIN_PRODUCT_TYPE fpt on tpd.FINPROD_ID = fpt.FINPROD_ID
            WHERE tpd.TRADE_MARKET in ('03','04') and tpd.FINPROD_TYPE2 in ('F02','F03') and fpt.TYPE_6='H01'
            )


                AND (
