		WITH VALID_TEMP AS(
			(
				 SELECT tpd.TRADE_ID TRADE_ID, fpt.TYPE_6 TYPE_6
				 FROM TRD_PRODUCT_DEAL tpd left join FIN_PRODUCT_TYPE fpt on tpd.FINPROD_ID = fpt.FINPROD_ID
